const body = $input.first().json.body || $input.first().json;
const raw_text = body.raw_text || body.rawText || null;
const drive_file_id = body.drive_file_id || body.driveFileId || null;
const source_document_name = body.source_document_name || body.sourceDocumentName || (raw_text ? 'pasted lead list' : 'drive file');
const source_url = body.source_url || body.sourceUrl || null;
const source_type = body.source_type || (raw_text ? 'paste' : 'drive');

if (!raw_text && !drive_file_id) {
  throw new Error('Need either raw_text or drive_file_id');
}

const run_id = 'leadingest_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,8);

return [{ json: {
  run_id,
  source_document_name,
  source_url,
  source_type,
  drive_file_id,
  raw_text: raw_text || null,
  has_raw_text: !!raw_text,
  received_at: new Date().toISOString(),
}}];

const meta = $('Validate').first().json;
let text = '';
if (meta.has_raw_text) {
  text = meta.raw_text;
} else {
  const drive = $input.first().json;
  text = typeof drive === 'string' ? drive : (drive.body || drive.data || JSON.stringify(drive));
}
return [{ json: { text: String(text).slice(0, 200000), source_document_name: meta.source_document_name, source_type: meta.source_type, run_id: meta.run_id }}];

