const item = $input.first().json;
let text = item.content?.[0]?.text || item.text || JSON.stringify(item);
text = text.trim();
if (text.startsWith('```')) {
  text = text.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}

let parsed;
try { parsed = JSON.parse(text); }
catch (e) {
  return [{ json: { ok: false, rejection_reason: 'invalid_json', raw_text: text.slice(0,2000), error: String(e) }}];
}

const ventures = $('Fetch venture_registry').first().json || [];
const ventureMap = {};
for (const v of ventures) ventureMap[v.slug] = v;

const meta = $('Validate').first().json;
const incoming = Array.isArray(parsed.leads) ? parsed.leads : [];

const clampScore = (v) => typeof v === 'number' ? Math.max(0, Math.min(100, Math.round(v))) : null;

const rows = [];
for (const l of incoming) {
  if (!l || typeof l !== 'object') continue;
  if (!l.full_name) continue;
  if (!l.email && !l.linkedin_url) continue;

  const scores = {};
  for (const slug of Object.keys(ventureMap)) {
    const s = (l.icp_scores || {})[slug];
    scores[slug] = clampScore(s) ?? 0;
  }

  // Determine primary_venture and tags.
  const tags = new Set();
  let bestSlug = null;
  let bestScore = -1;
  let bestSortOrder = 999;
  for (const slug of Object.keys(scores)) {
    const v = ventureMap[slug];
    const warm = v?.scoring_criteria?.tier_thresholds?.warm ?? 60;
    if (scores[slug] >= warm) {
      if (slug === 'mindmake') tags.add('mindmake_buyer');
      else if (v?.kind === 'podcast') {
        tags.add('podcast_guest_candidate');
        tags.add(slug + '_guest');
      } else {
        tags.add(slug + '_match');
      }
      const sort = v?.sort_order ?? 999;
      if (scores[slug] > bestScore || (scores[slug] === bestScore && sort < bestSortOrder)) {
        bestSlug = slug;
        bestScore = scores[slug];
        bestSortOrder = sort;
      }
    }
  }

  rows.push({
    full_name: String(l.full_name).slice(0,255),
    email: l.email || null,
    linkedin_url: l.linkedin_url || null,
    twitter_handle: l.twitter_handle || null,
    company: l.company || null,
    title: l.title || null,
    why_relevant: l.why_relevant || null,
    primary_tension: l.primary_tension || null,
    fit_score: clampScore(l.fit_score),
    attainability_score: clampScore(l.attainability_score),
    icp_score: scores.mindmake ?? null,  // legacy column, preserve for back-compat
    icp_scores: scores,
    primary_venture: bestSlug,
    tags: Array.from(tags),
    source_type: meta.source_type,
    source_ref: meta.run_id,
    source_document_name: meta.source_document_name,
    source_url: meta.source_url,
    raw_extraction: l,
    status: 'new',
    assignee_agent: bestSlug === 'mindmake' ? 'felix' : (bestSlug ? 'nell' : 'nell'),
  });
}

return rows.map(r => ({ json: r }));

const candidate = $input.first().json;
const contacted = $('Fetch contacted_persons').first().json || [];
const seenEmail = new Set();
const seenLink = new Set();
for (const c of contacted) {
  if (c.email) seenEmail.add(String(c.email).toLowerCase());
  if (c.linkedin_url) seenLink.add(String(c.linkedin_url).toLowerCase());
}

if (candidate.email && seenEmail.has(candidate.email.toLowerCase())) {
  return [];
}
if (candidate.linkedin_url && seenLink.has(candidate.linkedin_url.toLowerCase())) {
  return [];
}
return [{ json: candidate }];
